package typefacts;

import com.legend.compiler.element.type.PlatformTypes;
import com.legend.compiler.element.type.Type;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

/**
 * legend-lite's facts DataCube mirrors -- its type families and the pivot separator --
 * GENERATED by running legend-lite's own type lattice and constants
 * (docs/DATACUBE_TYPES_TO_SERVER_2026_09_27.md, decision D1): every type name either
 * compiler reports for a column -- legend-lite's plain primitives by leaf and by path,
 * legend-engine's precise primitives by path (each aliased to the parent legend-pure
 * declares) and Variant -- to its plain primitive and its family. Nothing is read out of
 * source text; the table is what {@link Type.Primitive} says.
 *
 * <p>Usage: {@code TypeFacts ts <out.ts>} (DataCube's copy, {@code //engine-client:lite_facts}) or
 * {@code TypeFacts py <out.py>} (Python's, {@code //engine-client:lite_facts_py}: the one table, for
 * Python's reading of a column's type -- docs/PYTHON_ASKS_DATACUBE_2026_10_15.md, item 4). Each
 * committed copy is diff-tested ({@code bazel run //engine-client:update_generated},
 * {@code bazel run //python:update_generated}).
 */
public final class TypeFacts {

    private TypeFacts() {
    }

    public static void main(String[] args) throws IOException {
        if (args.length != 2 || !(args[0].equals("ts") || args[0].equals("py") || args[0].equals("raise-ts")
                || args[0].equals("errors-ts"))) {
            throw new IllegalArgumentException("usage: TypeFacts ts|raise-ts|errors-ts|py <out>");
        }
        if (args[0].equals("errors-ts")) {
            // lite's error kinds and the status each is answered with (H4's P2, the user's CP-13 of 2026-11-19): a
            // module of their own, the one record of them lite-error.ts reads -- never a hand list
            Files.writeString(Path.of(args[1]), errorsTypescript(), StandardCharsets.UTF_8);
            return;
        }
        if (args[0].equals("raise-ts")) {
            // the raise's envelope and words, a module of their own: the tab loads them with raised.ts, on a
            // statement's first failure, never at startup (the orchestrator, 2026-11-15: the grid's bundle budget)
            Files.writeString(Path.of(args[1]), raiseTypescript(), StandardCharsets.UTF_8);
            return;
        }
        Map<String, String[]> facts = new TreeMap<>();
        for (Type.Primitive p : Type.Primitive.values()) {
            put(facts, p.typeName(), p);
            put(facts, p.qualifiedName(), p);
        }
        for (Map.Entry<String, Type.Primitive> e : Type.Primitive.byFqn().entrySet()) {
            put(facts, e.getKey(), e.getValue());
        }
        String variant = PlatformTypes.VARIANT.substring(PlatformTypes.VARIANT.lastIndexOf("::") + 2);
        facts.put(variant, new String[] {variant, "variant"});
        facts.put(PlatformTypes.VARIANT, new String[] {variant, "variant"});
        // Pure's top type: a column holding values of different types (a tree's label
        // column, an Ad Hoc column of several measures) is typed Any, as upstream types it
        String any = PlatformTypes.ANY.substring(PlatformTypes.ANY.lastIndexOf("::") + 2);
        facts.put(any, new String[] {any, "any"});
        facts.put(PlatformTypes.ANY, new String[] {any, "any"});

        String text = args[0].equals("ts") ? typescript(facts) : python(facts);
        Files.writeString(Path.of(args[1]), text, StandardCharsets.UTF_8);
    }

    private static String typescript(Map<String, String[]> facts) {
        StringBuilder out = new StringBuilder();
        out.append("// GENERATED by engine-client/tools/typefacts/TypeFacts.java, which RUNS legend-lite (its type\n")
                .append("// lattice, Type.Primitive, and its constants) -- DO NOT EDIT. Regenerate: bazel run //engine-client:update_generated;\n")
                .append("// its diff test fails the build if this copy drifts from legend-lite.\n")
                .append("// docs/DATACUBE_TYPES_TO_SERVER_2026_09_27.md, decision D1.\n\n")
                .append("/** A type's family, as legend-lite's lattice groups it (Type.Primitive.Family), Variant, and Pure's top type Any. */\n")
                .append("export type TypeFamily = 'numeric' | 'text' | 'boolean' | 'temporal' | 'binary' | 'variant' | 'any';\n\n")
                .append("/** A reported type name's plain primitive and its family. */\n")
                .append("export interface TypeFact {\n")
                .append("  readonly plain: string;\n")
                .append("  readonly family: TypeFamily;\n")
                .append("}\n\n")
                .append("/**\n")
                .append(" * Every type name a compiler reports for a column: legend-lite's plain primitives\n")
                .append(" * (by leaf and by path), legend-engine's precise primitives (by path, each to the\n")
                .append(" * parent legend-pure declares), Variant and Any.\n")
                .append(" */\n")
                .append("export const TYPE_FACTS: Readonly<Record<string, TypeFact>> = {\n");
        for (Map.Entry<String, String[]> e : facts.entrySet()) {
            out.append("  '").append(e.getKey()).append("': { plain: '").append(e.getValue()[0])
                    .append("', family: '").append(e.getValue()[1]).append("' },\n");
        }
        out.append("};\n\n")
                .append("/** How a pivot's generated column name joins its parts (Type.RelationType.PIVOT_SEPARATOR). */\n")
                .append("export const PIVOT_SEPARATOR = '")
                .append(Type.RelationType.PIVOT_SEPARATOR.replace("\\", "\\\\").replace("'", "\\'"))
                .append("';\n\n")
                .append("// LITE'S ARROW METADATA KEYS (result.ArrowKeys; H4's P10, 2026-11-19): every key a product Arrow answer\n")
                .append("// carries in its schema's or a field's metadata, never a literal of the host's own -- one constant each, so\n")
                .append("// a page's bundle carries the keys it reads alone.\n");
        for (Map.Entry<String, String> k : com.legend.result.ArrowKeys.all().entrySet()) {
            out.append("export const ARROW_KEY_").append(k.getKey()).append(" = '").append(k.getValue()).append("';\n");
        }
        return out.toString();
    }

    private static String raiseTypescript() {
        StringBuilder out = new StringBuilder();
        out.append("// GENERATED by engine-client/tools/typefacts/TypeFacts.java, which RUNS legend-lite (exec.RaisedErrors,\n")
                .append("// sql.RaiseKind) -- DO NOT EDIT. Regenerate: bazel run //engine-client:update_generated;\n")
                .append("// its diff test fails the build if this copy drifts from legend-lite. Read by raised.ts alone.\n\n")
                .append("/**\n")
                .append(" * A PRODUCT RAISE'S ENVELOPE (#104's M2(b), 2026-11-15): what a statement lite planned raises, as\n")
                .append(" * exec.RaisedErrors reads it -- between two SENTINELs, after an optional source position and POSITION_SEP, the\n")
                .append(" * site's TOKEN and its number (LG#<n>, read through the statement's site table: phase D's Phase 2,\n")
                .append(" * 2026-11-16); a quote the database could not hold as QUOTE_MARK. Its words are the plans' own (`sites`).\n")
                .append(" */\n")
                .append("export const RAISE = {\n")
                .append("  SENTINEL: '").append(unicode(com.legend.exec.RaisedErrors.SENTINEL)).append("',\n")
                .append("  POSITION_SEP: '").append(unicode(com.legend.exec.RaisedErrors.POSITION_SEP)).append("',\n")
                .append("  QUOTE_MARK: '").append(unicode(com.legend.exec.RaisedErrors.QUOTE_MARK)).append("',\n")
                .append("  TOKEN: '").append(unicode(com.legend.sql.RaiseKind.TOKEN.charAt(0)))
                .append(com.legend.sql.RaiseKind.TOKEN.substring(1)).append("',\n")
                .append("} as const;\n");
        return out.toString();
    }

    private static String errorsTypescript() {
        StringBuilder out = new StringBuilder();
        out.append("// GENERATED by engine-client/tools/typefacts/TypeFacts.java, which RUNS legend-lite (server.LiteV1Api.Kind)\n")
                .append("// -- DO NOT EDIT. Regenerate: bazel run //engine-client:update_generated; its diff test fails the build if\n")
                .append("// this copy drifts from legend-lite. Read by lite-error.ts alone (H4's P2, 2026-11-19).\n\n")
                .append("/** LITE'S ERROR KINDS (lite's API v1 spec §3), as every binding writes them: LiteV1Api.Kind's wire words, in\n")
                .append(" *  its order. */\n")
                .append("export const LITE_ERROR_KINDS = [");
        com.legend.server.LiteV1Api.Kind[] kinds = com.legend.server.LiteV1Api.Kind.values();
        for (int i = 0; i < kinds.length; i++) {
            out.append(i == 0 ? "" : ", ").append('\'').append(kinds[i].wire()).append('\'');
        }
        out.append("] as const;\n\n")
                .append("/** A refusal's kind. */\n")
                .append("export type LiteErrorKind = (typeof LITE_ERROR_KINDS)[number];\n\n")
                .append("/** The HTTP status a refusal of each kind is answered with (LiteV1Api.Kind.status). */\n")
                .append("export const LITE_ERROR_STATUS: Readonly<Record<LiteErrorKind, number>> = {\n");
        for (com.legend.server.LiteV1Api.Kind k : kinds) {
            out.append("  ").append(k.wire()).append(": ").append(k.status()).append(",\n");
        }
        out.append("};\n");
        return out.toString();
    }

    private static String python(Map<String, String[]> facts) {
        StringBuilder out = new StringBuilder();
        out.append("# GENERATED by engine-client/tools/typefacts/TypeFacts.java, which RUNS legend-lite (its type lattice,\n")
                .append("# Type.Primitive) -- DO NOT EDIT. Regenerate: bazel run //python:update_generated; its diff test fails the\n")
                .append("# build if this copy drifts from legend-lite. The same table as DataCube's\n")
                .append("# (engine-client/src/generated/lite-facts.ts): docs/DATACUBE_TYPES_TO_SERVER_2026_09_27.md, decision D1;\n")
                .append("# docs/PYTHON_ASKS_DATACUBE_2026_10_15.md, item 4.\n")
                .append("\"\"\"Every type name a compiler reports for a column -- legend-lite's plain primitives (by leaf and by path),\n")
                .append("legend-engine's precise primitives (by path, each to the parent legend-pure declares), Variant and Any -- to its\n")
                .append("plain primitive and its family (``_types.py`` reads it).\"\"\"\n\n")
                .append("TYPE_FACTS: dict[str, tuple[str, str]] = {\n");
        for (Map.Entry<String, String[]> e : facts.entrySet()) {
            out.append("    '").append(e.getKey()).append("': ('").append(e.getValue()[0])
                    .append("', '").append(e.getValue()[1]).append("'),\n");
        }
        out.append("}\n\n")
                .append("# A PRODUCT RAISE'S ENVELOPE (#104's M2(b), 2026-11-15), as exec.RaisedErrors reads it: between two\n")
                .append("# SENTINELs, after an optional source position and POSITION_SEP, a site's TOKEN and its number (LG#<n>, read\n")
                .append("# through the statement's site table: phase D's Phase 2, 2026-11-16); a quote the database could not hold as\n")
                .append("# QUOTE_MARK. The same as DataCube's (lite-facts.ts RAISE).\n")
                .append("RAISE_SENTINEL = '").append(unicode(com.legend.exec.RaisedErrors.SENTINEL)).append("'\n")
                .append("RAISE_POSITION_SEP = '").append(unicode(com.legend.exec.RaisedErrors.POSITION_SEP)).append("'\n")
                .append("RAISE_QUOTE_MARK = '").append(unicode(com.legend.exec.RaisedErrors.QUOTE_MARK)).append("'\n")
                .append("RAISE_TOKEN = '").append(unicode(com.legend.sql.RaiseKind.TOKEN.charAt(0)))
                .append(com.legend.sql.RaiseKind.TOKEN.substring(1)).append("'\n\n")
                .append("# LITE'S ARROW METADATA KEYS (result.ArrowKeys; H4's P10, 2026-11-19): every key a product Arrow answer\n")
                .append("# carries in its schema's or a field's metadata, never a literal of the host's own. The same as DataCube's\n")
                .append("# (lite-facts.ts ARROW_KEY_*).\n");
        for (Map.Entry<String, String> k : com.legend.result.ArrowKeys.all().entrySet()) {
            out.append("ARROW_KEY_").append(k.getKey()).append(" = '").append(k.getValue()).append("'\n");
        }
        return out.toString();
    }

    /** {@code c} as a {@code \\uXXXX} escape, which TypeScript and Python both read. */
    private static String unicode(char c) {
        return String.format(Locale.ROOT, "\\u%04x", (int) c);
    }

    private static void put(Map<String, String[]> facts, String name, Type.Primitive p) {
        facts.put(name, new String[] {p.typeName(), p.family().name().toLowerCase(Locale.ROOT)});
    }
}
